import sys
from collections import deque

def dfs(current_sequence, current_sum, index, n, k, r):
    if index == n:
        if current_sum % k == 0:
            print(' '.join(map(str, current_sequence)))
        return

    for i in range(1, r[index] + 1):
        current_sequence.append(i)
        dfs(current_sequence, current_sum + i, index + 1, n, k, r)
        current_sequence.pop()

def main():
    n, k = map(int, input().split())
    r = list(map(int, input().split()))

    total_sum = sum(r)
    if total_sum % k != 0:
        print()
        return

    dfs([], 0, 0, n, k, r)

if __name__ == "__main__":
    main()
