import sys
from typing import List

def build_segment_tree(arr: List[int], tree: List[int], node: int, start: int, end: int) -> None:
    if start == end:
        tree[node] = arr[start]
    else:
        mid = (start + end) // 2
        build_segment_tree(arr, tree, 2 * node + 1, start, mid)
        build_segment_tree(arr, tree, 2 * node + 2, mid + 1, end)
        tree[node] = tree[2 * node + 1] + tree[2 * node + 2]

def update_segment_tree(tree: List[int], node: int, start: int, end: int, index: int, value: int) -> None:
    if start == end:
        tree[node] = value
    else:
        mid = (start + end) // 2
        if index <= mid:
            update_segment_tree(tree, 2 * node + 1, start, mid, index, value)
        else:
            update_segment_tree(tree, 2 * node + 2, mid + 1, end, index, value)
        tree[node] = tree[2 * node + 1] + tree[2 * node + 2]

def query_segment_tree(tree: List[int], node: int, start: int, end: int, left: int, right: int) -> int:
    if left > end or right < start:
        return 0
    if left <= start and end <= right:
        return tree[node]
    mid = (start + end) // 2
    return query_segment_tree(tree, 2 * node + 1, start, mid, left, right) + query_segment_tree(tree, 2 * node + 2, mid + 1, end, left, right)

def main():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    X = list(map(int, data[1:N+1]))
    P = list(map(int, data[N+1:2*N+1]))
    Q = int(data[2*N+1])

    # Build the segment tree for the population array
    tree = [0] * (4 * N)
    build_segment_tree(P, tree, 0, 0, N-1)

    for _ in range(Q):
        L, R = map(int, data[2*N+2+2*_])
        # Adjust for 0-based indexing
        L -= 1
        R -= 1
        # Query the segment tree for the sum of populations in the range [L, R]
        print(query_segment_tree(tree, 0, 0, N-1, L, R))

if __name__ == "__main__":
    main()
```

This Python solution implements a segment tree to efficiently handle range queries and updates for the given problem. The `build_segment_tree` function initializes the segment tree, `update_segment_tree` updates the tree, and `query_segment_tree` retrieves the sum of populations within a specified range. The main function processes the input and outputs the results for each query.

