def is_11_22(s):
    n = len(s)
    if n % 2 == 0:
        return False
    mid = (n + 1) // 2
    return s[:mid] == '1' * (mid - 1) and s[mid] == '/' and s[mid + 1:] == '2' * (n - mid - 1)

