from collections import deque

def bfs(grid, start, D):
    H, W = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([start])
    visited = set([start])

    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 1 <= nx <= H and 1 <= ny <= W and grid[nx][ny] == '.' and (nx, ny) not in visited:
                if (nx, ny) == start or (nx, ny) == (x, y) + (dx, dy):
                    queue.append((nx, ny))
                    visited.add((nx, ny))
                elif abs(nx - x) + abs(ny - y) <= D:
                    queue.append((nx, ny))
                    visited.add((nx, ny))

    return visited

