import sys
from collections import defaultdict

def count_good_integers(N):
    # Initialize the sieve of Eratosthenes
    is_prime = [True] * (N + 1)
    p = 2
    while (p * p <= N):
        if (is_prime[p] == True):
            for i in range(p * p, N + 1, p):
                is_prime[i] = False
        p += 1

    # Count the frequency of each prime factor
    prime_factors = defaultdict(int)
    for i in range(2, N + 1):
        if is_prime[i]:
            j = i
            while j <= N:
                prime_factors[j] += 1
                j *= i

    # Calculate the number of good integers
    count = 0
    for a in range(1, int(N**0.5) + 1):
        for b in range(1, int(N**(1/4)) + 1):
            if (2**a * b**2 <= N):
                count += prime_factors[2**a] * prime_factors[b**2]

    return count

# Read input
