import sys
from functools import lru_cache

sys.setrecursionlimit(10**6)
MOD = 998244353

def count_polish_sequences(n, a):
    @lru_cache(None)
    def dp(i, j):
        if i == n:
            return 1
        count = 0
        for k in range(j + 1):
            if a[i] >= k:
                count = (count + dp(i + 1, k)) % MOD
        return count

    return dp(0, 0)

if __name__ == "__main__":
    n = int(input())
    a = list(map(int, input().split()))
    result = count_polish_sequences(n, a)
    print(result)
