import sys
from typing import List

def find(x: int, parent: List[int]) -> int:
    if parent[x] != x:
        parent[x] = find(parent[x], parent)
    return parent[x]

def union(x: int, y: int, parent: List[int], rank: List[int]) -> None:
    root_x = find(x, parent)
    root_y = find(y, parent)
    if root_x == root_y:
        return
    if rank[root_x] > rank[root_y]:
        parent[root_y] = root_x
    elif rank[root_x] < rank[root_y]:
        parent[root_x] = root_y
    else:
        parent[root_y] = root_x
        rank[root_x] += 1

def count_connected_components(arr: List[int]) -> int:
    n = len(arr)
    parent = list(range(n))
    rank = [0] * n
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] <= arr[j]:
                union(i, j, parent, rank)
    return len(set(find(i, parent) for i in range(n)))

def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    M = int(data[1])
    B = list(map(int, data[2:]))

