import sys
from typing import List

def matrix_multiply(A: List[List[int]], B: List[List[int]], p: int) -> List[List[int]]:
    N = len(A)
    C = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            for k in range(N):
                C[i][j] += A[i][k] * B[k][j]
                C[i][j] %= p
    return C

def matrix_power(matrix: List[List[int]], exp: int, p: int) -> List[List[int]]:
    result = [[1] * len(matrix) for _ in range(len(matrix))]
    base = matrix
    while exp > 0:
        if exp % 2 == 1:
            result = matrix_multiply(result, base, p)
        base = matrix_multiply(base, base, p)
        exp //= 2
    return result

def solve():
    N, p = map(int, input().split())
    A = [list(map(int, input().split())) for _ in range(N)]

    # Replace zeros with random numbers between 1 and p-1
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                A[i][j] = (i + j) % (p - 1) + 1

    # Compute B^p
    B_p = matrix_power(A, p, p)

    # Print the result
    for row in B_p:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    solve()
```

