from collections import deque

def bfs(graph, start, end):
    queue = deque([(start, end)])
    visited = set()
    visited.add((start, end))

    while queue:
        current_a, current_b = queue.popleft()

        # Check if we have reached the goal
        if current_a == end and current_b == start:
            return len(queue)

        # Explore all possible moves
        for neighbor in graph[current_a]:
            if neighbor != current_b:
                new_state = (neighbor, current_b)
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append(new_state)

        for neighbor in graph[current_b]:
            if neighbor != current_a:
                new_state = (current_a, neighbor)
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append(new_state)

    return -1

def main():
    N, M, S, T = map(int, input().split())
