def main():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    Q = int(data[1])
    A = list(map(int, data[2:2+N]))
    queries = []

    for _ in range(Q):
        u = int(data[2+2+N+2*_]) - 1
        v = int(data[2+2+N+2*_+1]) - 1
        queries.append((u, v))

    MOD = 998244353

    def dfs(node, parent, depth):
        nonlocal dist
        dist[node] = depth
        for child in adj[node]:
            if child != parent:
                dfs(child, node, depth + 1)

    def lca(u, v):
        if dist[u] > dist[v]:
            u, v = v, u
        for _ in range(dist[v] - dist[u]):
            v = parent[v]
        while u != v:
            u = parent[u]
            v = parent[v]
        return u

    def get_distance(u, v):
        l = lca(u, v)
        return dist[u] + dist[v] - 2 * dist[l]

    for u, v in queries:
        dist = [0] * N
        adj = [[] for _ in range(N)]

        for i in range(2, N+1):
            adj[A[i-1]].append(i)

