        total_distance = 0
        for perm in permutations(range(2, N+1)):
            new_adj = [[] for _ in range(N)]
            for i in range(2, N+1):
                new_adj[perm[i-1]].append(i)

            new_dist = [0] * N
            dfs(1, -1, 0)

            if get_distance(u, v) == get_distance(perm[u], perm[v]):
