```python
import sys
from functools import lru_cache

sys.setrecursionlimit(10**6)

MOD = 998244353

def main():
    T = int(input())
    for _ in range(T):
        H, W = map(int, input().split())
        S = [input() for _ in range(H)]

        @lru_cache(None)
        def dp(i, j, a, b):
            if i == H and j == W:
                return 1
            if i == H:
                return dp(0, j, a, b)
            if j == W:
                return dp(i, 0, a, b)

            count = 0
            if S[i][j] == 'A':
                # Try placing a Type-A tile
                if (j + 1) % W != 0 and (i + 1) % H != 0:
                    count += dp(i, (j + 1) % W, a + 1, b)
                if (j - 1) >= 0 and (i + 1) % H != 0:
                    count += dp(i, (j - 1) % W, a + 1, b)
                if (j + 1) % W != 0 and (i - 1) >= 0:
                    count += dp((i - 1) % H, j, a + 1, b)
                if (j - 1) >= 0 and (i - 1) >= 0:
                    count += dp((i - 1) % H, (j - 1) % W, a + 1, b)
            elif S[i][j] == 'B':
                # Try placing a Type-B tile
                if (j + 1) % W != 0 and (i + 1) % H != 0:
                    count += dp(i, (j + 1) % W, a, b + 1)
                if (j - 1) >= 0 and (i + 1) % H != 0:
                    count += dp(i, (j - 1) % W, a, b + 1)
                if (j + 1) % W != 0 and (i - 1) >= 0:
                    count += dp((i - 1) % H, j, a, b + 1)
                if (j - 1) >= 0 and (i - 1) >= 0:
                    count += dp((i - 1) % H, (j - 1) % W, a, b + 1)

            return count % MOD

        result = dp(0, 0, 0, 0)
        print(result)

if __name__ == "__main__":
    main()
```

