```python
from collections import defaultdict
import sys

MOD = 998244353

def dfs(i, j, a, b, dp):
    if (i, j, a, b) in dp:
        return dp[(i, j, a, b)]

    if i == H and j == W:
        return 1

    count = 0
    if i < H:
        if j < W - 1:
            if S[i][j] == 'A':
                count += dfs(i, j + 1, a + 1, b, dp)
            else:
                count += dfs(i, j + 1, a, b + 1, dp)
        if j > 0:
            if S[i][j - 1] == 'A':
                count += dfs(i, j - 1, a + 1, b, dp)
            else:
                count += dfs(i, j - 1, a, b + 1, dp)
    if j < W:
        if i < H - 1:
            if S[i][j] == 'A':
                count += dfs((i + 1) % H, j, a + 1, b, dp)
            else:
                count += dfs((i + 1) % H, j, a, b + 1, dp)
        if i > 0:
            if S[i - 1][j] == 'A':
                count += dfs((i - 1) % H, j, a + 1, b, dp)
            else:
                count += dfs((i - 1) % H, j, a, b + 1, dp)

    count %= MOD
    dp[(i, j, a, b)] = count
    return count

def main():
    T = int(input())
    for _ in range(T):
        H, W = map(int, input().split())
        S = [input() for _ in range(H)]

        dp = defaultdict(int)
        result = dfs(0, 0, 0, 0, dp)
        print(result)

if __name__ == "__main__":
    main()
```

